//! Emits `hg-ucd`'s tables.
//!
//! Every table is a sorted `static` array searched by binary search at
//! run time, so `hg-ucd` needs no allocation, no build script and no
//! `unsafe`. The output is checked in and its freshness is a test
//! (CS-ST-17, G16), as `hg-opgen`'s is.

use std::fmt::Write as _;

use crate::ucd::{QuickCheck, Ucd};

/// The header every generated file carries (CS-ST-17).
fn header(version: &str) -> String {
    format!(
        "// @generated by hg-unicode-build from the Unicode Character \
         Database {version}.\n// Do not edit: run `cargo run -p hg-unicode-build -- generate`.\n\n"
    )
}

/// UTS #46 status words, in the order the generated `Status` enum gives
/// them. Taken from UTS #46 Section 5's table.
pub const STATUSES: [&str; 6] = [
    "valid",
    "ignored",
    "mapped",
    "deviation",
    "disallowed",
    "disallowed_STD3_valid",
];

/// `disallowed_STD3_mapped` shares a discriminant with `mapped` and a
/// flag, so it is listed apart.
const STD3_MAPPED: &str = "disallowed_STD3_mapped";

fn quick_bits(q: QuickCheck) -> u8 {
    match q {
        QuickCheck::Yes => 0,
        QuickCheck::Maybe => 1,
        QuickCheck::No => 2,
    }
}

/// Writes the whole of `tables.rs`.
#[must_use]
#[expect(
    clippy::too_many_lines,
    reason = "one function per generated file keeps the emitted order obvious"
)]
pub fn tables(u: &Ucd) -> String {
    let mut out = header(&u.version);
    out.push_str(
        "//! The Unicode Character Database, as sorted tables.\n\
         //!\n\
         //! Each table is searched by binary search on its first column.\n\
         //! The decomposition tables hold *fully expanded* mappings, so a\n\
         //! reader never recurses (UAX #15: the mappings are applied\n\
         //! recursively, and doing that here keeps it out of the hot path).\n\n",
    );

    let _ = writeln!(
        out,
        "/// The version of the database these tables were built from.\n\
         pub const VERSION: &str = \"{}\";\n",
        u.version
    );

    // --- canonical combining class ---------------------------------------
    out.push_str(
        "/// Canonical combining class, for the code points whose class is\n\
         /// not zero. Sorted by code point.\n\
         pub static CCC: &[(u32, u8)] = &[\n",
    );
    for (cp, c) in &u.ccc {
        let _ = writeln!(out, "    (0x{cp:04X}, {c}),");
    }
    out.push_str("];\n\n");

    // --- decompositions ---------------------------------------------------
    let mut pool: Vec<char> = Vec::new();
    let mut canon: Vec<(u32, u32, u8)> = Vec::new();
    let mut compat: Vec<(u32, u32, u8)> = Vec::new();
    for cp in u.decomp.keys() {
        let c = u.canonical(*cp);
        if c.len() != 1 || c.first().map(|x| u32::from(*x)) != Some(*cp) {
            canon.push(push_pool(&mut pool, &c, *cp));
        }
        let k = u.compatibility(*cp);
        if k.len() != 1 || k.first().map(|x| u32::from(*x)) != Some(*cp) {
            compat.push(push_pool(&mut pool, &k, *cp));
        }
    }

    out.push_str(
        "/// Every decomposition's characters, run together. The index\n\
         /// tables below give each mapping's offset and length.\n\
         pub static POOL: &[char] = &[\n",
    );
    for chunk in pool.chunks(8) {
        out.push_str("   ");
        for c in chunk {
            let _ = write!(out, " '\\u{{{:04X}}}',", u32::from(*c));
        }
        out.push('\n');
    }
    out.push_str("];\n\n");

    emit_index(
        &mut out,
        "CANONICAL",
        "Fully expanded canonical decompositions: `(code point, offset into\n/// [`POOL`], length)`, sorted by code point.",
        &canon,
    );
    emit_index(
        &mut out,
        "COMPATIBILITY",
        "Fully expanded compatibility decompositions, which include the\n/// canonical ones: `(code point, offset into [`POOL`], length)`.",
        &compat,
    );

    // --- primary composites ----------------------------------------------
    out.push_str(
        "/// The primary composites of UAX #15: the key packs the starter in\n\
         /// the high 32 bits and the combining character in the low 32, and\n\
         /// the value is the composite. Sorted by key. Composites excluded\n\
         /// by `Full_Composition_Exclusion` are not here.\n\
         pub static COMPOSE: &[(u64, u32)] = &[\n",
    );
    for ((a, b), c) in u.compositions() {
        let key = (u64::from(a) << 32) | u64::from(b);
        let _ = writeln!(out, "    (0x{key:016X}, 0x{c:04X}),");
    }
    out.push_str("];\n\n");

    // --- quick check ------------------------------------------------------
    out.push_str(
        "/// Quick-check values (UAX #15, Table 1) for the code points whose\n\
         /// value is not `Yes` in some form, as ranges. The byte packs two\n\
         /// bits per form, NFC first then NFD, NFKC and NFKD: 0 `Yes`, 1\n\
         /// `Maybe`, 2 `No`.\n\
         pub static QUICK_CHECK: &[(u32, u32, u8)] = &[\n",
    );
    let mut qc: Vec<(u32, u8)> = u
        .quick_check
        .iter()
        .map(|(cp, forms)| {
            let bits = forms.iter().enumerate().fold(0_u8, |acc, (i, q)| {
                acc | (quick_bits(*q) << (u8::try_from(i).unwrap_or(0) * 2))
            });
            (*cp, bits)
        })
        .filter(|(_, bits)| *bits != 0)
        .collect();
    qc.sort_unstable();
    for (first, last, bits) in runs(&qc) {
        let _ = writeln!(out, "    (0x{first:04X}, 0x{last:04X}, 0b{bits:08b}),");
    }
    out.push_str("];\n\n");

    // --- UTS 46 -----------------------------------------------------------
    out.push_str(
        "/// UTS #46's status per code point range, and the mapping where the\n\
         /// status has one: `(first, last, status, offset into [`IDNA_POOL`],\n\
         /// length)`. The status is an index into [`STATUS_NAMES`]; bit 7 of\n\
         /// it marks `disallowed_STD3_mapped`, which maps like `mapped` but\n\
         /// is disallowed when STD3 rules are on.\n\
         pub static IDNA: &[(u32, u32, u8, u32, u8)] = &[\n",
    );
    let mut idna_pool: Vec<char> = Vec::new();
    for r in &u.idna {
        let (status, std3) = match r.status.as_str() {
            s if s == STD3_MAPPED => (2_u8, 0x80_u8),
            s => (
                u8::try_from(STATUSES.iter().position(|n| *n == s).unwrap_or(4)).unwrap_or(4),
                0,
            ),
        };
        let (off, len) = if r.mapping.is_empty() {
            (0_u32, 0_u8)
        } else {
            let off = u32::try_from(idna_pool.len()).unwrap_or(0);
            idna_pool.extend_from_slice(&r.mapping);
            (off, u8::try_from(r.mapping.len()).unwrap_or(0))
        };
        let _ = writeln!(
            out,
            "    (0x{:04X}, 0x{:04X}, {}, {off}, {len}),",
            r.first,
            r.last,
            status | std3
        );
    }
    out.push_str("];\n\n");

    out.push_str(
        "/// The characters every UTS #46 mapping is made of.\n\
         pub static IDNA_POOL: &[char] = &[\n",
    );
    for chunk in idna_pool.chunks(8) {
        out.push_str("   ");
        for c in chunk {
            let _ = write!(out, " '\\u{{{:04X}}}',", u32::from(*c));
        }
        out.push('\n');
    }
    out.push_str("];\n\n");

    out.push_str("/// UTS #46's status words, indexed by the status byte.\npub static STATUS_NAMES: &[&str] = &[\n");
    for n in STATUSES {
        let _ = writeln!(out, "    \"{n}\",");
    }
    out.push_str("];\n");

    out
}

/// Appends `to` to `pool` and returns the index row for `cp`.
fn push_pool(pool: &mut Vec<char>, to: &[char], cp: u32) -> (u32, u32, u8) {
    let off = u32::try_from(pool.len()).unwrap_or(0);
    pool.extend_from_slice(to);
    (cp, off, u8::try_from(to.len()).unwrap_or(0))
}

fn emit_index(out: &mut String, name: &str, doc: &str, rows: &[(u32, u32, u8)]) {
    let _ = writeln!(out, "/// {doc}");
    let _ = writeln!(out, "pub static {name}: &[(u32, u32, u8)] = &[");
    for (cp, off, len) in rows {
        let _ = writeln!(out, "    (0x{cp:04X}, {off}, {len}),");
    }
    out.push_str("];\n\n");
}

/// Collapses a sorted `(code point, value)` list into inclusive runs of
/// equal value, which makes the quick-check table about a tenth the size.
fn runs(sorted: &[(u32, u8)]) -> Vec<(u32, u32, u8)> {
    let mut out: Vec<(u32, u32, u8)> = Vec::new();
    for (cp, bits) in sorted {
        match out.last_mut() {
            Some(last) if last.2 == *bits && last.1.saturating_add(1) == *cp => last.1 = *cp,
            _ => out.push((*cp, *cp, *bits)),
        }
    }
    out
}
